// ดึงข้อมูล Item แรกออกมา
const item = $input.first();

// เข้าถึงค่า apiKey ตาม Path ที่คุณต้องการ
const apiKey = item.json.body.apiKey;

// Return กลับไปเป็น Array ตามรูปแบบที่ n8n ต้องการ
return [
  {
    json: {
      apiKey: apiKey
    }
  }
];

// ==========================================
// 1. ตั้งค่าเวลาและรับข้อมูล
// ==========================================
const item = $input.first();
const row = item.json; // ข้อมูลจาก Google Sheets

// 🕒 เวลาปัจจุบัน (Thai Time: GMT+7)
const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Bangkok" }));

// ⚠️ รับ Input Key: พยายามดึงจาก Webhook Node (Body หรือ Query)
let inputKey;
try {
    // แก้ชื่อ 'Webhook' ให้ตรงกับชื่อ Node ของคุณ
    const webhookData = $('/api/verify-key').first().json;
    inputKey = webhookData.body?.apiKey || webhookData.query?.apiKey;
} catch (e) { 
    // ถ้าหา Webhook ไม่เจอ (เช่นตอน Test) ให้ใช้ค่าจาก Sheet แทน
    inputKey = row.api_key; 
}

// ==========================================
// 2. ดึงค่าจาก Database (Sheet)
// ==========================================
// เช็คว่าเจอข้อมูลใน Sheet หรือไม่
const isFoundInDb = row && row.api_key && Object.keys(row).length > 0;

const isActive = row.is_active;       // สถานะเปิด/ปิด
const limit = Number(row.limit || 0); // ลิมิตใช้งานสูงสุด
const used = Number(row.used || 0);   // จำนวนที่ใช้ไปแล้ว

// ==========================================
// 📅 เช็ควันหมดอายุ (ใช้ช่อง date_last_used)
// ==========================================
let isExpired = false;
let expireDate = null;

if (isFoundInDb && row.date_last_used) {
    // ใช้ date_last_used เป็น "วันหมดอายุ"
    expireDate = new Date(row.date_last_used);

    // ตั้งเวลาให้หมดอายุตอน "วินาทีสุดท้าย" ของวันนั้น (23:59:59)
    expireDate.setHours(23, 59, 59, 999);

    // ถ้า "เวลาปัจจุบัน" เลย "วันหมดอายุ" ไปแล้ว
    if (now > expireDate) {
        isExpired = true;
    }
}

// ==========================================
// 3. Logic ตัดสินใจ (สร้าง Response)
// ==========================================
let finalResponse = {};

// ❌ 1. ไม่ส่ง Key มา (400)
if (!inputKey) {
  finalResponse = { 
    code: 400, 
    body: { success: false, error: "Missing apiKey (ไม่พบ API Key ในคำขอ)" } 
  };
}

// ❌ 2. หาไม่เจอ หรือ Key ไม่ตรง (401)
else if (!isFoundInDb || String(row.api_key).trim() !== String(inputKey).trim()) {
  finalResponse = { 
    code: 401, 
    body: { success: false, error: "Invalid API Key (รหัสไม่ถูกต้อง)" } 
  };
}

// ❌ 3. ถูกปิดใช้งาน (Inactive) (403)
else if (isActive === false || String(isActive) === "false") {
  finalResponse = { 
    code: 403, 
    body: { success: false, error: "Account Suspended (ถูกระงับการใช้งาน)" } 
  };
}

// ❌ 4. หมดอายุ (Expired) (403)
else if (isExpired) {
  finalResponse = { 
    code: 403, 
    body: { 
      success: false, 
      error: "API Key Expired (หมดอายุการใช้งาน)",
      valid_until: row.date_last_used 
    } 
  };
}

// ❌ 5. เครดิตหมด (Limit Exceeded) (403)
else if (used >= limit) {
  finalResponse = { 
    code: 403, 
    body: { success: false, error: "Credit Limit Exceeded (ยอดใช้งานเต็ม)" } 
  };
}

// ✅ 6. ผ่านทุกเงื่อนไข (200)
else {
  finalResponse = {
    code: 200,
    body: { 
      success: true, 
      status: "verified", 
      message: "ตรวจสอบสิทธิ์สำเร็จ",
      data: {
          user: row.user_id,
          remaining: limit - used,
          valid_until: row.date_last_used
      }
    }
  };
}

// ส่งค่าออกไปให้ Node ถัดไป
return [
  {
    json: {
      finalResponse: finalResponse,
      // ส่งข้อมูลเดิมไปด้วย เผื่อใช้ Update ยอด used
      keyData: row 
    }
  }
];

// Function node — คืนค่าเป็น requestBody เดียว (item.json === requestBody)
// อ่าน prompt จาก $input.first().json.body.prompt และไฟล์จาก items[0].binary หรือ body.files

function binToBase64(binObj) {
  if (!binObj) return null;
  if (binObj.data && Buffer.isBuffer(binObj.data)) return binObj.data.toString('base64');
  if (binObj.data && typeof binObj.data === 'string') return binObj.data;
  try { return Buffer.from(binObj).toString('base64'); } catch (e) { return null; }
}

const item = items[0];
const body = item.json?.body || {};
const prompt = body.prompt || "";
const aspectRatio = body.aspectRatio || "1:1";
const imageSize = body.imageSize; // optional

// build parts
const parts = [];
if (prompt) parts.push({ text: prompt });

let providedImages = 0;
if (item.binary && Object.keys(item.binary).length > 0) {
  const keys = Object.keys(item.binary).sort();
  for (const k of keys) {
    const bin = item.binary[k];
    const b64 = binToBase64(bin);
    if (!b64) continue;
    const inlinePart = { inlineData: { data: b64 } };
    if (bin.mimeType) inlinePart.inlineData.mimeType = bin.mimeType;
    parts.push(inlinePart);
    providedImages++;
  }
}
if (Array.isArray(body.files)) {
  for (const f of body.files) {
    const b64 = f.data || f.content_b64 || f.base64;
    if (!b64) continue;
    const inlinePart = { inlineData: { data: b64 } };
    if (f.mimeType) inlinePart.inlineData.mimeType = f.mimeType;
    parts.push(inlinePart);
    providedImages++;
  }
}

// fallback if no images
const numberOfImages = providedImages > 0 ? providedImages : 1;

// build requestBody only (top-level item.json)
const requestBody = {
  contents: [
    {
      parts: parts
    }
  ],
  generationConfig: {
    responseModalities: ["IMAGE"],
    imageConfig: {
      aspectRatio: aspectRatio,
      // ถ้าต้องการใส่ imageSize ให้แน่ใจว่าโมเดลรองรับ
      ...(imageSize ? { imageSize: imageSize } : {})
      // note: ไม่บังคับใส่ numberOfImages ถ้าโมเดลไม่รองรับ
    }
  }
};

// คืนค่าเป็น item.json = requestBody (HTTP Request node ให้ส่ง Raw body = {{$json}})
items[0].json = requestBody;
return items;

const res = items[0];

if (res.error) {
  return [
    {
      json: {
        success: false,
        message: `ผิดพลาดในการส่งข้อมูลไปยัง Gemini (${res.error.httpCode})`,
        hint: "โปรดตรวจสอบ API Key, Model หรือ Payload",
        details: res.error.message
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      images: res.json
    }
  }
];

// 1. ดึงข้อมูลทั้งหมดที่เข้ามา
const items = $input.all();

// 2. ค้นหาชิ้นส่วนข้อมูล (ใช้วิธีค้นหาเผื่อลำดับสลับกัน)
// หา item ที่มี 'body' (ข้อมูลจาก Webhook)
const webhookItem = items.find(item => item.json.body && item.json.body.user_id);
// หา item ที่มี 'webViewLink' (ข้อมูลจาก Drive)
const driveItem = items.find(item => item.json.webViewLink);

// ดึงไส้ในออกมาเตรียมไว้ (ถ้าหาไม่เจอให้เป็น Object ว่างๆ ป้องกัน Error)
const webhookData = webhookItem ? webhookItem.json.body : {};
const driveLink = driveItem ? driveItem.json.webViewLink : null;

// 3. สร้าง Object ใหม่ที่สะอาดและรวมร่างแล้ว
const cleanData = {
  // --- ส่วนข้อมูล User ---
  userId: webhookData.user_id,
  apiKey: webhookData.api_key, // หรือจะตัดออกก็ได้ถ้าเป็นความลับ

  // --- ส่วนคำสั่ง (Prompt) ---
  action: webhookData.action,
  mode: webhookData.prompt_mode,
  prompt: webhookData.finalPrompt,

  // --- ส่วนผลลัพธ์ (Output) ---
  status: webhookData.status || 'unknown',
  // เอา Link จาก Item ที่ 2 มาใส่ตรงนี้
  resultImage: driveLink, 

  // --- ส่วนเวลา (Time) ---
  // แปลงเวลาให้ดูง่ายขึ้น (Readable Date)
  requestTime: webhookData.timestamp,
  processedTime: new Date().toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' })
};

// 4. ส่งออกเป็น 1 Item
return [
  {
    json: cleanData
  }
];
